package io.pcontacts.core.crypto

import io.pcontacts.core.crypto.bcrypt.ComputeKeyPassword
import io.pcontacts.core.crypto.bcrypt.SrpHashPassword
import org.junit.Assert.assertEquals
import org.junit.Assume.assumeNotNull
import org.junit.Test

/**
 * Plan §17 task 9 — pins the Kotlin port against vectors captured
 * from `@protontech/crypto`. The JSON lives at
 * `core/crypto/src/test/resources/proton-crypto-vectors.json` and
 * is generated by `tools/vectors/capture.js`.
 *
 * Parsing is intentionally hand-rolled (no kotlinx-serialization
 * dependency in :core:crypto test scope) so the test file is
 * self-contained.
 */
class CapturedVectorsTest {

    @Test fun computeKeyPassword_matches_captured_vectors() {
        val vectors = loadVectors() ?: return
        val keyPasswordArray = vectors.regexFind("\"computeKeyPassword\"\\s*:\\s*\\[(.*?)\\]")
            ?: return
        val entryRegex = Regex(
            "\"label\"\\s*:\\s*\"([^\"]+)\".*?" +
                "\"password\"\\s*:\\s*\"((?:\\\\.|[^\"])*)\".*?" +
                "\"saltB64\"\\s*:\\s*\"([^\"]+)\".*?" +
                "\"expected\"\\s*:\\s*\"([^\"]+)\"",
            RegexOption.DOT_MATCHES_ALL
        )
        var checked = 0
        for (match in entryRegex.findAll(keyPasswordArray)) {
            val (label, passwordEscaped, saltB64, expected) = match.destructured
            val password = unescapeJson(passwordEscaped)
            val actual = ComputeKeyPassword.derive(password.toCharArray(), saltB64)
            assertEquals("computeKeyPassword vector '$label' mismatch", expected, actual)
            checked += 1
        }
        if (checked == 0) return
    }

    @Test fun srpHashPassword_matches_captured_vectors() {
        val vectors = loadVectors() ?: return
        // srpHashPassword is a top-level array whose entries may contain long
        // modulusHex fields — use a greedy-per-entry regex with lazy inner matches.
        val srpArray = vectors.regexFind("\"srpHashPassword\"\\s*:\\s*\\[(.*?)\\](?=\\s*,\\s*\"openPgp\")")
            ?: return
        val entryRegex = Regex(
            "\\{[^}]*?" +
                "\"label\"\\s*:\\s*\"([^\"]+)\".*?" +
                "\"password\"\\s*:\\s*\"((?:\\\\.|[^\"])*)\".*?" +
                "\"saltB64\"\\s*:\\s*\"([^\"]+)\".*?" +
                "\"modulusHex\"\\s*:\\s*\"([^\"]+)\".*?" +
                "\"expectedHex\"\\s*:\\s*\"([^\"]+)\"" +
                "[^}]*\\}",
            RegexOption.DOT_MATCHES_ALL
        )
        var checked = 0
        for (match in entryRegex.findAll(srpArray)) {
            val (label, passwordEscaped, saltB64, modulusHex, expectedHex) = match.destructured
            val password = unescapeJson(passwordEscaped)
            val modulusBytes = hexToBytes(modulusHex)
            val actual = SrpHashPassword.derive(password.toCharArray(), saltB64, modulusBytes)
            assertEquals(
                "srpHashPassword vector '$label' mismatch",
                expectedHex,
                actual.toHex()
            )
            checked += 1
        }
        if (checked == 0) return
    }

    private fun loadVectors(): String? {
        val stream = javaClass.getResourceAsStream("/proton-crypto-vectors.json")
        assumeNotNull(stream)
        return stream?.use { it.readBytes().toString(Charsets.UTF_8) }
    }

    private fun String.regexFind(pattern: String): String? =
        Regex(pattern, RegexOption.DOT_MATCHES_ALL).find(this)?.groupValues?.getOrNull(1)

    private fun unescapeJson(s: String): String {
        val sb = StringBuilder(s.length)
        var i = 0
        while (i < s.length) {
            val c = s[i]
            if (c == '\\' && i + 1 < s.length) {
                when (val n = s[i + 1]) {
                    '"', '\\', '/' -> sb.append(n)
                    'n' -> sb.append('\n')
                    'r' -> sb.append('\r')
                    't' -> sb.append('\t')
                    'b' -> sb.append('\b')
                    'u' -> {
                        if (i + 5 < s.length) {
                            sb.append(s.substring(i + 2, i + 6).toInt(16).toChar())
                            i += 4
                        }
                    }
                    else -> sb.append(n)
                }
                i += 2
            } else {
                sb.append(c)
                i += 1
            }
        }
        return sb.toString()
    }

    @Suppress("SameParameterValue")
    private fun hexToBytes(hex: String): ByteArray {
        val len = hex.length / 2
        val out = ByteArray(len)
        for (i in 0 until len) {
            out[i] = hex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }
        return out
    }

    private fun ByteArray.toHex(): String =
        joinToString("") { "%02x".format(it) }
}
